  /// < Invalid parameter
  static const int MEDIADEMUXER_ERROR_INVALID_PARAMETER = -22;

  /// < Invalid operation
  static const int MEDIADEMUXER_ERROR_INVALID_OPERATION = -38;

  /// < Not supported
  static const int MEDIADEMUXER_ERROR_NOT_SUPPORTED = -1073741822;

  /// < Permission denied
  static const int MEDIADEMUXER_ERROR_PERMISSION_DENIED = -13;

  /// < Invalid state
  static const int MEDIADEMUXER_ERROR_INVALID_STATE = -27131903;

  /// < Invalid path
  static const int MEDIADEMUXER_ERROR_INVALID_PATH = -27131902;

  /// < Resource limit
  static const int MEDIADEMUXER_ERROR_RESOURCE_LIMIT = -27131901;

  /// < Seek operation failure
